func TestRedactSummary_WithSecrets(t *testing.T) {
	t.Parallel()
	summary := &Summary{
		Intent:  "Set API_KEY=" + highEntropySecret,
		Outcome: "Configured key " + highEntropySecret + " successfully",
		Friction: []string{
