			for _, part := range msg.Parts {
				if part.Type == "tool" && part.State != nil {
					entries = append(entries, Entry{
						Type:       EntryTypeTool,
						ToolName:   part.Tool,
						ToolDetail: extractOpenCodeToolDetail(part.State.Input),
